    UPDATE provider_balance_monitor SET balance_amount=#{balance},is_available=#{available},alert_state=#{state},alert_id=#{alertId},alert_sent_at=#{sentAt},
  last_checked_at=UTC_TIMESTAMP(6),check_count=check_count+1,last_error_code=NULL,updated_at=UTC_TIMESTAMP(6)
WHERE monitor_key=#{key} AND lease_token=#{token}
